import { AlertTriangle, CreditCard, Mail, Phone, Receipt, User } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { useCartStore } from '../store'
import type { CustomerDetail } from '@/features/customers/types'

// ============================================================================
// Component — PosSidebar
// Sticky right panel showing the selected customer (with missing-info
// indicators), running totals, and the prominent Pay button. Designed to
// stay visible while the cashier scans items so the customer can see the
// running total on screen.
// ============================================================================

export interface PosSidebarProps {
  /** Cached selected customer from CustomerSelector (null = walk-in / unselected) */
  selectedCustomer: CustomerDetail | null
  /** True if a customer has been picked (controls walk-in vs empty styling) */
  hasCustomer: boolean
  /** Open the payment dialog */
  onPay: () => void
}

export function PosSidebar({ selectedCustomer, hasCustomer, onPay }: PosSidebarProps) {
  const subtotalNet = useCartStore((s) => s.subtotalNet)
  const vatTotal = useCartStore((s) => s.vatTotal)
  const totalGross = useCartStore((s) => s.totalGross)
  const canCheckout = useCartStore((s) => s.canCheckout)
  const itemCount = useCartStore((s) => s.lineItems.length)

  return (
    <aside className="w-80 shrink-0 hidden lg:flex flex-col gap-4 sticky top-4 self-start">
      {/* ── Customer Card ──────────────────────────── */}
      <CustomerCard
        customer={selectedCustomer}
        hasCustomer={hasCustomer}
      />

      {/* ── Totals + Pay Card ──────────────────────── */}
      <TotalsCard
        subtotalNet={subtotalNet}
        vatTotal={vatTotal}
        totalGross={totalGross}
        itemCount={itemCount}
        canCheckout={canCheckout}
        onPay={onPay}
      />
    </aside>
  )
}

// ============================================================================
// Sub-component — CustomerCard
// Shows selected customer with name/phone/email + ⚠ icons for missing fields.
// Walk-in state: dashed border with "Walk-in (anonymous)" label.
// ============================================================================

interface CustomerCardProps {
  customer: CustomerDetail | null
  hasCustomer: boolean
}

function CustomerCard({ customer, hasCustomer }: CustomerCardProps) {
  return (
    <div
      className={`glass-card glass-card-accent relative overflow-hidden animate-fade-in-up ${
        hasCustomer ? 'border-l-4 border-l-cyan-400' : 'border-dashed border-white/15'
      }`}
    >
      {/* Subtle color halo when customer is set */}
      {hasCustomer && (
        <div
          className="absolute inset-0 rounded-2xl bg-gradient-to-br from-cyan-500/10 via-transparent to-violet-500/5 opacity-50 pointer-events-none"
          aria-hidden
        />
      )}

      {/* Header */}
      <div className="relative z-[1] flex items-center justify-between gap-2 px-5 pt-5 pb-3">
        <div className="flex items-center gap-2.5 min-w-0">
          <div
            className={`flex h-8 w-8 items-center justify-center rounded-lg ring-1 ring-white/10 ${
              hasCustomer
                ? 'bg-gradient-to-br from-cyan-500/25 to-blue-600/15 shadow-[0_0_18px_rgba(34,211,238,.22)]'
                : 'bg-white/[.04]'
            }`}
          >
            <User
              size={16}
              className={hasCustomer ? 'text-cyan-300/90' : 'text-muted-foreground/70'}
              strokeWidth={2.2}
            />
          </div>
          <h2 className="text-sm font-semibold tracking-wide text-foreground/90 uppercase">
            Customer
          </h2>
        </div>
        {hasCustomer && customer?.type && (
          <span
            className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full ring-1 ${
              customer.type === 'private'
                ? 'bg-cyan-500/10 text-cyan-300/90 ring-cyan-400/20'
                : 'bg-violet-500/10 text-violet-300/90 ring-violet-400/20'
            }`}
          >
            {customer.type}
          </span>
        )}
      </div>

      {/* Animated underline */}
      <div className="relative z-[1] h-px mx-5 animated-underline" aria-hidden />

      {/* Body */}
      <div className="relative z-[1] p-5">
        {hasCustomer && customer ? (
          <div className="space-y-2.5">
            <p className="text-base font-semibold text-foreground/95 truncate">
              {customer.displayName}
            </p>
            <div className="space-y-1.5">
              <CustomerField
                icon={Phone}
                label="Phone"
                value={customer.phone}
                hasValue={!!customer.phone}
              />
              <CustomerField
                icon={Mail}
                label="Email"
                value={customer.email}
                hasValue={!!customer.email}
              />
            </div>
          </div>
        ) : (
          <div className="text-center py-3">
            <p className="text-sm text-muted-foreground/80 italic">
              Walk-in (anonymous)
            </p>
            <p className="text-[11px] text-muted-foreground/60 mt-1">
              No customer attached to this sale
            </p>
          </div>
        )}
      </div>
    </div>
  )
}

// ============================================================================
// Sub-component — CustomerField
// One row in the customer card. Shows icon + label + value, or ⚠ if missing.
// ============================================================================

interface CustomerFieldProps {
  icon: typeof Phone
  label: string
  value: string | null | undefined
  hasValue: boolean
}

function CustomerField({ icon: Icon, label, value, hasValue }: CustomerFieldProps) {
  return (
    <div className="flex items-center gap-2 text-xs">
      <Icon
        size={13}
        className={hasValue ? 'text-muted-foreground/80 shrink-0' : 'text-muted-foreground/40 shrink-0'}
        strokeWidth={2}
      />
      <span className="text-muted-foreground/70 shrink-0">{label}:</span>
      {hasValue ? (
        <span className="text-foreground/85 truncate">{value}</span>
      ) : (
        <span
          className="inline-flex items-center gap-1 text-amber-300/80"
          title={`${label} not on file`}
        >
          <AlertTriangle size={11} strokeWidth={2.2} className="shrink-0" />
          <span className="italic text-[11px]">missing</span>
        </span>
      )}
    </div>
  )
}

// ============================================================================
// Sub-component — TotalsCard
// The always-visible price counter. Large total in emerald glow when ready
// to pay, muted when not.
// ============================================================================

interface TotalsCardProps {
  subtotalNet: number
  vatTotal: number
  totalGross: number
  itemCount: number
  canCheckout: boolean
  onPay: () => void
}

function TotalsCard({ subtotalNet, vatTotal, totalGross, itemCount, canCheckout, onPay }: TotalsCardProps) {
  return (
    <div className="glass-card glass-card-accent relative overflow-hidden animate-fade-in-up border-l-4 border-l-emerald-400">
      {/* Subtle emerald halo when ready to pay */}
      <div
        className={`absolute inset-0 rounded-2xl bg-gradient-to-br from-emerald-500/12 via-transparent to-cyan-500/8 transition-opacity duration-500 pointer-events-none ${
          canCheckout ? 'opacity-90' : 'opacity-30'
        }`}
        aria-hidden
      />

      {/* Header */}
      <div className="relative z-[1] flex items-center justify-between gap-2 px-5 pt-5 pb-3">
        <div className="flex items-center gap-2.5 min-w-0">
          <div
            className={`flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-emerald-500/25 to-cyan-600/15 ring-1 ring-white/10 transition-shadow duration-300 ${
              canCheckout
                    ? 'shadow-[0_0_22px_rgba(16,185,129,.35)]'
                    : 'shadow-[0_0_10px_rgba(16,185,129,.10)]'
                }`}
          >
            <Receipt size={16} className="text-emerald-300/90" strokeWidth={2.2} />
          </div>
          <h2 className="text-sm font-semibold tracking-wide text-foreground/90 uppercase">
            Total
          </h2>
        </div>
        {itemCount > 0 && (
          <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-300/90 ring-1 ring-emerald-400/20 tabular-nums">
            {itemCount} {itemCount === 1 ? 'item' : 'items'}
          </span>
        )}
      </div>

      {/* Animated underline */}
      <div className="relative z-[1] h-px mx-5 animated-underline" aria-hidden />

      {/* Body */}
      <div className="relative z-[1] p-5 space-y-2">
        <TotalRow label="Subtotal (net)" value={subtotalNet} />
        <TotalRow label="VAT" value={vatTotal} />

        <div className="pt-2 mt-2 border-t border-white/[.06]">
          <div className="flex items-baseline justify-between">
            <span className="text-xs font-semibold uppercase tracking-wider text-muted-foreground/80">
              Grand total
            </span>
            <span
              className={`text-2xl font-extrabold tabular-nums value-flash ${
                canCheckout ? 'text-emerald-300/95 text-glow-emerald' : 'text-muted-foreground/60'
              }`}
            >
              {formatPrice(totalGross)}
            </span>
          </div>
        </div>

        {/* Pay button */}
        <Button
          onClick={onPay}
          disabled={!canCheckout}
          size="lg"
          className={`w-full mt-3 h-12 text-base font-semibold transition-all duration-300 ${
            canCheckout
              ? 'bg-gradient-to-r from-emerald-500 to-cyan-500 hover:from-emerald-400 hover:to-cyan-400 text-white border-0 shadow-[0_0_20px_rgba(16,185,129,.45)] hover:shadow-[0_0_28px_rgba(16,185,129,.6)] hover:scale-[1.02]'
              : ''
          }`}
        >
          <CreditCard size={18} strokeWidth={2.4} className="mr-2" />
          {itemCount === 0 ? 'Add items to pay' : canCheckout ? 'Pay now' : 'Cannot pay yet'}
        </Button>
      </div>
    </div>
  )
}

// ============================================================================
// Sub-component — TotalRow
// One line in the totals card (Subtotal, VAT). Small label + price.
// ============================================================================

function TotalRow({ label, value }: { label: string; value: number }) {
  return (
    <div className="flex items-baseline justify-between text-sm">
      <span className="text-muted-foreground/80">{label}</span>
      <span className="font-mono tabular-nums text-foreground/85">{formatPrice(value)}</span>
    </div>
  )
}

// ============================================================================
// Helpers
// ============================================================================

function formatPrice(cents: number): string {
  const euros = (cents / 100).toFixed(2)
  return `€${euros}`
}

import crypto from 'crypto'
import { db } from '@/db/index.js'
import {
  customers,
  sales,
  quotes,
  repairs,
  customerOrders,
  backorders,
  invoices,
  bicycles,
  type Customer as DbCustomer
} from '@/db/schema.js'
import { and, asc, eq, sql } from 'drizzle-orm'
import { createCustomerSchema, updateCustomerSchema, type CreateCustomerInput, type UpdateCustomerInput } from '@shared/validations/customer.js'

// ---------------------------------------------------------------------------
// DTO shapes returned by the API (compact customer selector item)
// ---------------------------------------------------------------------------

/**
 * Compact customer shape for dropdown selectors.
 *
 * Only includes id, display name, and type — no PII exposed.
 */
export interface CustomerSelectorItem {
  /** Unique customer identifier */
  id: string
  /** Human-readable name: "firstName lastName" for private, companyName for company */
  displayName: string
  /** 'private' or 'company' */
  type: 'private' | 'company'
}

/** Response envelope for the customer list endpoint. */
export interface CustomerListResponse {
  customers: CustomerSelectorItem[]
}

/** Query parameters for the paginated/managed customer list. */
export interface CustomerListQuery {
  /** Search term — filters across displayName, email, and phone */
  search?: string
  /** Page number (1-indexed) */
  page?: number
  /** Items per page */
  pageSize?: number
}

/** Paginated response for the management list endpoint. */
export interface CustomerPaginatedResponse {
  customers: CustomerDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Public API — Read operations
// ---------------------------------------------------------------------------

/**
 * Get all customers formatted as a compact list suitable for dropdown selectors.
 *
 * Display name is computed from domain fields:
 * - Private customers: "firstName lastName"
 * - Company customers: companyName
 *
 * @returns Customer selector items sorted by display name
 */
export async function getCustomerList(): Promise<CustomerListResponse> {
  const results = await listCustomers()

  return {
    customers: results.map(toSelectorItem)
  }
}

/**
 * Get paginated customer list with optional search filtering.
 *
 * Returns full CustomerDetail records suitable for the management view.
 * Search filters across display name, email, and phone fields.
 *
 * @param query - Optional search term, page number, and page size
 * @returns Paginated response with customers and pagination metadata
 */
export async function getCustomerListPaginated(
  query: CustomerListQuery = {}
): Promise<CustomerPaginatedResponse> {
  const { search, page = 1, pageSize = 25 } = query
  const offset = (page - 1) * pageSize

  // Build filter conditions for search
  let whereClause: ReturnType<typeof and> | undefined

  if (search && search.trim()) {
    const term = `%${search.trim()}%`
    whereClause = and(
      sql`LOWER(CONCAT(${customers.firstName}, ' ', ${customers.lastName}, ' ', ${customers.companyName}, ' ', ${customers.email}, ' ', ${customers.phone})) LIKE ${term.toLowerCase()}`
    )
  }

  // Get total count for pagination
  let totalCount = 0
  if (whereClause) {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(customers).where(whereClause)
    totalCount = count
  } else {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(customers)
    totalCount = count
  }

  // Get paginated results
  let results: DbCustomer[]
  if (whereClause) {
    results = await db.select().from(customers).where(whereClause)
      .orderBy(
        asc(
          sql`CASE WHEN ${customers.type} = 'private' THEN ${customers.lastName} ELSE ${customers.companyName} END`
        )
      )
      .limit(pageSize)
      .offset(offset)
  } else {
    results = await db.select().from(customers)
      .orderBy(
        asc(
          sql`CASE WHEN ${customers.type} = 'private' THEN ${customers.lastName} ELSE ${customers.companyName} END`
        )
      )
      .limit(pageSize)
      .offset(offset)
  }

  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize))

  return {
    customers: results.map(toCustomerDetail),
    totalItems: totalCount,
    currentPage: page,
    pageSize,
    totalPages
  }
}

