import { useState } from 'react'
import { Package, Wrench, Sparkles } from 'lucide-react'
import { PartsSearch } from './PartsSearch'
import { LaborSearch } from './LaborSearch'

// ============================================================================
// Component — Add Items Section
// Tabbed container for the three ways to add items to the cart:
//   - Parts:    barcode + name search + Special Product creation (current behavior)
//   - Labor:    search-as-you-type service picker with conditional form
//   - Special:  reserved for future use (gift cards, custom services, etc.)
// ============================================================================

type TabId = 'parts' | 'labor' | 'special'

interface TabConfig {
  id: TabId
  label: string
  icon: typeof Package
  /** Whether the tab has a working implementation */
  enabled: boolean
}

const TABS: TabConfig[] = [
  { id: 'parts', label: 'Parts', icon: Package, enabled: true },
  { id: 'labor', label: 'Labor', icon: Wrench, enabled: true },
  { id: 'special', label: 'Special', icon: Sparkles, enabled: false },
]

export function AddItemsSection() {
  const [activeTab, setActiveTab] = useState<TabId>('parts')

  return (
    <div className="flex flex-col gap-3">
      {/* Tab strip */}
      <div role="tablist" aria-label="Add items category" className="inline-flex rounded-md border border-white/[.08] bg-white/[.02] p-0.5 self-start">
        {TABS.map((tab) => {
          const Icon = tab.icon
          const isActive = activeTab === tab.id
          return (
            <button
              key={tab.id}
              type="button"
              role="tab"
              aria-selected={isActive}
              aria-controls={`add-items-panel-${tab.id}`}
              id={`add-items-tab-${tab.id}`}
              onClick={() => setActiveTab(tab.id)}
              disabled={!tab.enabled}
              className={`inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded transition-colors ${
                isActive
                  ? 'bg-cyan-500/15 text-cyan-300/95 ring-1 ring-cyan-400/30'
                  : tab.enabled
                    ? 'text-muted-foreground/80 hover:text-foreground/90 hover:bg-white/[.04]'
                    : 'text-muted-foreground/40 cursor-not-allowed'
              }`}
            >
              <Icon size={13} strokeWidth={2.2} />
              {tab.label}
            </button>
          )
        })}
      </div>

      {/* Tab panels */}
      <div
        role="tabpanel"
        id={`add-items-panel-${activeTab}`}
        aria-labelledby={`add-items-tab-${activeTab}`}
      >
        {activeTab === 'parts' && <PartsSearch />}
        {activeTab === 'labor' && <LaborSearch />}
        {activeTab === 'special' && <SpecialTabPlaceholder />}
      </div>
    </div>
  )
}

