import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { render, screen, waitFor, act } from '@testing-library/react'
import { PosPage } from '../routes/PosPage'
import { useCartStore } from '../store'
import type { CustomerDetail } from '@/features/customers/types'

// ── Mock fetch ─────────────────────────────────────────────────────
//
// PosPage calls `GET /api/customers/:id` to populate the sidebar's
// customer cache. The list endpoint (`/api/customers`) is the compact
// shape and does NOT contain email/phone — only the detail endpoint does.

interface MockRoute {
  match: (url: string) => boolean
  respond: (url: string) => Promise<Response>
}

function mockFetchRoutes(routes: MockRoute[]) {
  const mockFn = vi.fn().mockImplementation(async (url: string | URL | Request) => {
    const urlString = url.toString()
    for (const route of routes) {
      if (route.match(urlString)) {
        return route.respond(urlString)
      }
    }
    return { ok: false, status: 404 } as Response
  })
  vi.stubGlobal('fetch', mockFn)
  return mockFn
}

/** Build a /api/customers/:id route that dispatches by id. */
function customerDetailRouteById(customers: Record<string, CustomerDetail | null>): MockRoute {
  return {
    match: (url) => /\/api\/customers\/[^/?]+$/.test(url),
    respond: async (url) => {
      const match = url.match(/\/api\/customers\/([^/?]+)$/)
      const id = match?.[1] ?? ''
      const customer = customers[id]
      if (!customer) {
        return {
          ok: false,
          status: 404,
          json: async () => ({ error: 'Customer not found' }),
        } as Response
      }
      return {
        ok: true,
        status: 200,
        json: async () => customer,
      } as Response
    },
  }
}

// ── Reset cart store ───────────────────────────────────────────────

function resetStore() {
  useCartStore.setState({
    lineItems: [],
    customerId: null,
    checkoutError: null,
    checkoutSuccess: null,
    isCheckingOut: false,
    subtotalNet: 0,
    vatTotal: 0,
    totalGross: 0,
    canCheckout: false,
  })
}

// ── Test data ──────────────────────────────────────────────────────

const alicePrivate: CustomerDetail = {
  id: 'cust-alice',
  displayName: 'Alice Smith',
  type: 'private',
  firstName: 'Alice',
  lastName: 'Smith',
  vatId: null,
  phone: '+32 470 11 22 33',
  email: 'alice@example.com',
  street: null,
  number: null,
  bus: null,
  postalCode: null,
  city: null,
  country: 'BE',
  notificationPreference: null,
}

const bobMissingContact: CustomerDetail = {
  id: 'cust-bob',
  displayName: 'Bob Jones',
  type: 'private',
  firstName: 'Bob',
  lastName: 'Jones',
  vatId: null,
  phone: null,
  email: null,
  street: null,
  number: null,
  bus: null,
  postalCode: null,
  city: null,
  country: 'BE',
  notificationPreference: null,
}

// ── Tests ──────────────────────────────────────────────────────────

describe('PosPage — sidebar customer card (email/phone display)', () => {
  beforeEach(() => {
    resetStore()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('fetches the selected customer via GET /api/customers/:id (NOT the list endpoint)', async () => {
    const fetchSpy = mockFetchRoutes([
      customerDetailRouteById({ [alicePrivate.id]: alicePrivate }),
    ])

    useCartStore.getState().setCustomer(alicePrivate.id)
    render(<PosPage />)

    await waitFor(() => {
      // Should call the detail endpoint with the id, never the bare /api/customers
      const calls = fetchSpy.mock.calls.map((c) => c[0].toString())
      expect(calls.some((c) => c.includes(`/api/customers/${alicePrivate.id}`))).toBe(true)
      expect(calls.some((c) => /\/api\/customers\/?$/.test(c))).toBe(false)
    }, { timeout: 2000 })
  })

  it('shows the selected customer email and phone in the sidebar', async () => {
    mockFetchRoutes([
      customerDetailRouteById({ [alicePrivate.id]: alicePrivate }),
    ])

    useCartStore.getState().setCustomer(alicePrivate.id)
    render(<PosPage />)

    // Email + phone should appear (not "missing")
    await waitFor(() => {
      expect(screen.getByText('alice@example.com')).toBeInTheDocument()
      expect(screen.getByText('+32 470 11 22 33')).toBeInTheDocument()
    }, { timeout: 2000 })
  })

  it('shows "missing" warning when email/phone are null', async () => {
    mockFetchRoutes([
      customerDetailRouteById({ [bobMissingContact.id]: bobMissingContact }),
    ])

    useCartStore.getState().setCustomer(bobMissingContact.id)
    render(<PosPage />)

    // Two "missing" indicators should appear (email + phone)
    await waitFor(() => {
      const missingLabels = screen.getAllByText(/missing/i)
      expect(missingLabels.length).toBeGreaterThanOrEqual(2)
    }, { timeout: 2000 })

    // Bob's name should still display
    expect(screen.getByText('Bob Jones')).toBeInTheDocument()
  })

  it('updates the sidebar when the selected customer changes', async () => {
    const fetchSpy = mockFetchRoutes([
      customerDetailRouteById({
        [alicePrivate.id]: alicePrivate,
        [bobMissingContact.id]: bobMissingContact,
      }),
    ])

    // Start with Alice
    useCartStore.getState().setCustomer(alicePrivate.id)
    render(<PosPage />)

    await waitFor(() => {
      expect(screen.getByText('alice@example.com')).toBeInTheDocument()
    }, { timeout: 2000 })

    // Switch to Bob
    await act(async () => {
      useCartStore.getState().setCustomer(bobMissingContact.id)
    })

    // Bob's data should appear, Alice's email should be gone
    await waitFor(() => {
      expect(screen.queryByText('alice@example.com')).not.toBeInTheDocument()
      expect(screen.getByText('Bob Jones')).toBeInTheDocument()
      const missingLabels = screen.getAllByText(/missing/i)
      expect(missingLabels.length).toBeGreaterThanOrEqual(2)
    }, { timeout: 2000 })

    // Should have called the detail endpoint for both ids
    const calls = fetchSpy.mock.calls.map((c) => c[0].toString())
    expect(calls.some((c) => c.includes(`/api/customers/${alicePrivate.id}`))).toBe(true)
    expect(calls.some((c) => c.includes(`/api/customers/${bobMissingContact.id}`))).toBe(true)
  })

  it('clears the cached customer when customerId becomes null (walk-in)', async () => {
    mockFetchRoutes([
      customerDetailRouteById({ [alicePrivate.id]: alicePrivate }),
    ])

    useCartStore.getState().setCustomer(alicePrivate.id)
    render(<PosPage />)

    await waitFor(() => {
      expect(screen.getByText('alice@example.com')).toBeInTheDocument()
    }, { timeout: 2000 })

    // Switch to walk-in
    await act(async () => {
      useCartStore.getState().setCustomer(null)
    })

    await waitFor(() => {
      expect(screen.queryByText('alice@example.com')).not.toBeInTheDocument()
    }, { timeout: 2000 })

    // The sidebar's customer card should show its walk-in body text
    // (distinct from the selector's "Walk-in or pick a customer" subtitle).
    // Use a query that scopes to the sidebar aside element.
    const sidebar = document.querySelector('aside')
    expect(sidebar).not.toBeNull()
    expect(sidebar!.textContent).toMatch(/Walk-in \(anonymous\)/)
    // Subtitle that should NOT be present in the sidebar (only in the left section)
    expect(sidebar!.textContent).not.toMatch(/Walk-in or pick a customer/)
  })
})

import { useState, useRef, useEffect, useCallback } from 'react'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { useCartStore, type LaborBillingType } from '../store'

// ============================================================================
// Types
// ============================================================================

/** Labor service as returned by GET /api/repairs/labor-services */
interface LaborServiceOption {
  id: string
  name: string
  description: string | null
  billingType: LaborBillingType
  defaultRate: number // cents (per hour for hourly, fixed amount for fixed)
}

interface LaborServicesResponse {
  laborServices: LaborServiceOption[]
  total: number
}

// ============================================================================
// Component — Labor Search
// Search-as-you-type service picker with a conditional form (minutes for
// hourly, none for fixed) and a live price preview. On submit, calls
// `addLaborLineItem` with the correct mode.
// ============================================================================

export function LaborSearch() {
  const addLaborLineItem = useCartStore((s) => s.addLaborLineItem)

  const [searchTerm, setSearchTerm] = useState('')
  const [results, setResults] = useState<LaborServiceOption[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [highlightedIndex, setHighlightedIndex] = useState(-1)
  const [isDropdownOpen, setIsDropdownOpen] = useState(false)

  const [selectedService, setSelectedService] = useState<LaborServiceOption | null>(null)
  const [minutes, setMinutes] = useState('') // string for input control; parsed on submit

  const searchRef = useRef<HTMLInputElement>(null)

  // Debounced text search — fetches services from GET /api/repairs/labor-services?search=
  useEffect(() => {
    if (!searchTerm.trim()) {
      setResults([])
      setIsDropdownOpen(false)
      return
    }

    const timer = setTimeout(async () => {
      setIsLoading(true)
      try {
        const response = await fetch(
          `/api/repairs/labor-services?search=${encodeURIComponent(searchTerm.trim())}`
        )
        if (response.ok) {
          const data = (await response.json()) as LaborServicesResponse
          setResults(data.laborServices)
          setIsDropdownOpen(data.laborServices.length > 0)
        } else {
          setResults([])
          setIsDropdownOpen(false)
        }
      } catch {
        setResults([])
        setIsDropdownOpen(false)
      } finally {
        setIsLoading(false)
      }
    }, 250)

    return () => clearTimeout(timer)
  }, [searchTerm])

  /** Pick a service from the dropdown — resets minutes and refocuses search */
  const handlePickService = useCallback((service: LaborServiceOption) => {
    setSelectedService(service)
    setSearchTerm('')
    setResults([])
    setIsDropdownOpen(false)
    setHighlightedIndex(-1)
    setMinutes(service.billingType === 'hourly' ? '30' : '')
  }, [])

  /** Add the selected service (with minutes) to the cart */
  const handleAddToCart = useCallback(() => {
    if (!selectedService) return

    if (selectedService.billingType === 'hourly') {
      const parsedMinutes = parseInt(minutes, 10)
      if (!minutes || isNaN(parsedMinutes) || parsedMinutes <= 0) return
      addLaborLineItem({
        mode: 'hourly',
        description: selectedService.name,
        minutesWorked: parsedMinutes,
        hourlyRateSnapshot: selectedService.defaultRate,
        laborServiceId: selectedService.id,
      })
    } else {
      addLaborLineItem({
        mode: 'fixed',
        description: selectedService.name,
        fixedRate: selectedService.defaultRate,
        laborServiceId: selectedService.id,
      })
    }

    // Reset for next entry
    setSelectedService(null)
    setMinutes('')
    searchRef.current?.focus()
  }, [selectedService, minutes, addLaborLineItem])

  /** Cancel current selection and return to search */
  const handleCancelSelection = useCallback(() => {
    setSelectedService(null)
    setMinutes('')
    setSearchTerm('')
    setResults([])
    setIsDropdownOpen(false)
    searchRef.current?.focus()
  }, [])

  // Live price preview for hourly services
  const livePriceCents =
    selectedService?.billingType === 'hourly'
      ? Math.round((parseInt(minutes, 10) / 60) * selectedService.defaultRate)
      : selectedService?.billingType === 'fixed'
        ? selectedService.defaultRate
        : 0

  const isAddDisabled =
    !selectedService ||
    (selectedService.billingType === 'hourly' &&
      (!minutes || isNaN(parseInt(minutes, 10)) || parseInt(minutes, 10) <= 0))

  // Keyboard navigation for the dropdown
  const handleSearchKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (!isDropdownOpen || results.length === 0 || selectedService) return

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault()
          setHighlightedIndex((prev) => Math.min(prev + 1, results.length - 1))
          break
        case 'ArrowUp':
          e.preventDefault()
          setHighlightedIndex((prev) => Math.max(prev - 1, 0))
          break
        case 'Enter':
          e.preventDefault()
          if (highlightedIndex >= 0 && highlightedIndex < results.length) {
            handlePickService(results[highlightedIndex])
          } else if (results.length === 1) {
            handlePickService(results[0])
          }
          break
        case 'Escape':
          e.preventDefault()
          setIsDropdownOpen(false)
          setHighlightedIndex(-1)
          break
      }
    },
    [isDropdownOpen, results, highlightedIndex, handlePickService, selectedService]
  )

  return (
    <div className="flex flex-col gap-3">
      {/* Search input — search-as-you-type service picker */}
      <div className="relative">
        <Label htmlFor="labor-search" className="text-sm font-medium text-muted-foreground mb-1 block">
          Search Services
        </Label>
        <Input
          id="labor-search"
          ref={searchRef}
          placeholder="Search by service name..."
          value={searchTerm}
          onChange={(e) => {
            setSearchTerm(e.target.value)
            setSelectedService(null)
          }}
          onKeyDown={handleSearchKeyDown}
          disabled={!!selectedService}
          aria-autocomplete="list"
          aria-expanded={isDropdownOpen}
          aria-controls="labor-search-results"
        />

        {/* Service dropdown — each row shows name + price + billing type badge */}
        {isDropdownOpen && results.length > 0 && !selectedService && (
          <div
            id="labor-search-results"
            role="listbox"
            className="absolute z-50 w-full mt-1 border rounded-md bg-background shadow-lg max-h-48 overflow-y-auto"
          >
            {results.map((service, index) => {
              const isHighlighted = index === highlightedIndex
              return (
                <button
                  key={service.id}
                  type="button"
                  role="option"
                  aria-selected={isHighlighted}
                  onClick={() => handlePickService(service)}
                  className={`w-full text-left px-3 py-2 border-b last:border-b-0 flex items-center justify-between transition-colors ${
                    isHighlighted ? 'bg-accent' : 'hover:bg-accent/70 cursor-pointer'
                  }`}
                >
                  <div className="flex-1 min-w-0">
                    <div className="font-medium truncate">{service.name}</div>
                    {service.description && (
                      <div className="text-xs text-muted-foreground truncate">{service.description}</div>
                    )}
                  </div>
                  <div className="ml-3 flex items-center gap-2 shrink-0">
                    <BillingTypeBadge billingType={service.billingType} />
                    <span className="text-sm font-mono">{formatPrice(service.defaultRate)}</span>
                    {!isHighlighted && (
                      <span className="text-xs text-muted-foreground">+ Add</span>
                    )}
                  </div>
                </button>
              )
            })}
          </div>
        )}

        {/* No results message */}
        {!isLoading && searchTerm.trim() && !isDropdownOpen && !selectedService && (
          <div className="text-sm text-muted-foreground text-center py-4">No services found</div>
        )}

        {isLoading && !selectedService && (
          <div className="text-sm text-muted-foreground text-center py-4">Loading...</div>
        )}
      </div>

      {/* Conditional form — shown after a service is picked */}
      {selectedService && (
        <div className="p-3 border rounded-md bg-muted/30 space-y-3">
          {/* Picked service summary */}
          <div className="flex items-center justify-between gap-2">
            <div className="min-w-0">
              <div className="text-sm font-medium truncate">{selectedService.name}</div>
              <div className="text-xs text-muted-foreground flex items-center gap-2">
                <BillingTypeBadge billingType={selectedService.billingType} />
                <span className="font-mono">{formatPrice(selectedService.defaultRate)}{selectedService.billingType === 'hourly' ? '/hr' : ''}</span>
              </div>
            </div>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={handleCancelSelection}
              className="shrink-0"
            >
              Change
            </Button>
          </div>

          {/* Hourly: minutes input + live price preview */}
          {selectedService.billingType === 'hourly' && (
            <div className="space-y-2">
              <Label htmlFor="labor-minutes" className="text-xs">
                Minutes worked *
              </Label>
              <Input
                id="labor-minutes"
                type="number"
                inputMode="numeric"
                placeholder="e.g. 30"
                value={minutes}
                onChange={(e) => setMinutes(e.target.value)}
                min="1"
              />
              {parseInt(minutes, 10) > 0 && (
                <div className="text-xs text-muted-foreground font-mono tabular-nums">
                  Price preview: <span className="text-foreground/90 font-semibold">{formatPrice(livePriceCents)}</span>
                  {' '}({minutes}min × {formatPrice(selectedService.defaultRate)}/hr ÷ 60)
                </div>
              )}
            </div>
          )}

          {/* Fixed: just show the price (no input needed) */}
          {selectedService.billingType === 'fixed' && (
            <div className="text-xs text-muted-foreground">
              Flat price: <span className="font-mono font-semibold text-foreground/90">{formatPrice(livePriceCents)}</span>
            </div>
          )}

          {/* Add to cart button */}
          <Button
            type="button"
            onClick={handleAddToCart}
            disabled={isAddDisabled}
            className="w-full"
          >
            Add to Cart — {formatPrice(livePriceCents)}
          </Button>
        </div>
      )}
    </div>
  )
}

// ============================================================================
// Sub-component — Billing Type Badge
// Mirrors the catalog table's billing column (Hourly / Fixed pill).
// ============================================================================

function BillingTypeBadge({ billingType }: { billingType: LaborBillingType }) {
  const config = {
    hourly: { label: 'Hourly', classes: 'bg-cyan-500/15 text-cyan-300/90 ring-cyan-400/25' },
    fixed: { label: 'Fixed', classes: 'bg-violet-500/15 text-violet-300/90 ring-violet-400/25' },
  }[billingType]

  return (
    <span
      className={`inline-flex items-center px-1.5 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider ring-1 ${config.classes}`}
    >
      {config.label}
    </span>
  )
}

// ============================================================================
// Helpers
// ============================================================================

/** Format cents to currency string */
function formatPrice(cents: number): string {
  const euros = (cents / 100).toFixed(2)
  return `€${euros}`
}

